arguments.rule_content:
{
  "title": "Suspicious DLL Load by spoolsv.exe",
  "id": "local-001",
  "description": "Detects loading of DLLs from non-standard paths by spoolsv.exe, indicative of PrintNightmare exploitation.",
  "status": "experimental",
  "author": "SOC",
  "logsource": {
    "product": "windows",
    "service": "sysmon"
  },
  "detection": {
    "selection": {
      "Image": "*\\spoolsv.exe",
      "ImageLoaded": "*\\Windows\\Temp\\*.dll"
    },
    "condition": "selection"
  },
  "level": "high",
  "tags": ["attack.t1068", "cve-2021-34527"]
}
